// List Running Models sample shape, https://github.com/ollama/ollama/blob/v0.34.4/docs/api.md.
func ollamaPSLoaded(name string, contextLength any) map[string]any {
	return map[string]any{"models": []map[string]any{{
		"name":           name,
		"model":          name,
		"size":           5137025024,
		"expires_at":     "2024-06-04T14:38:31.83753-07:00",
		"size_vram":      5137025024,
		"context_length": contextLength,
	}}}
}

type ollamaFixture struct {
	srv  *httptest.Server
	mu   sync.Mutex
	auth map[string][]string
}

func newOllamaFixture(t *testing.T, show, ps any) *ollamaFixture {
	t.Helper()
	f := &ollamaFixture{auth: map[string][]string{}}
	record := func(next http.Handler) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			f.mu.Lock()
			f.auth[r.URL.Path] = append(f.auth[r.URL.Path], r.Header.Get("Authorization"))
			f.mu.Unlock()
			next.ServeHTTP(w, r)
		}
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/api/tags", record(jsonHandler(map[string]any{"models": []map[string]any{{"name": "x"}}})))
	if show != nil {
		mux.HandleFunc("/api/show", record(jsonHandler(show)))
	}
	if ps != nil {
		mux.HandleFunc("/api/ps", record(jsonHandler(ps)))
	}
	f.srv = httptest.NewServer(mux)
	t.Cleanup(f.srv.Close)
	return f
}

func (f *ollamaFixture) detect(t *testing.T, modelName, apiKey string) (*system.ModelApiSpec, []string) {
	t.Helper()
	api, trace := newTestDetector().DetectWithTrace(context.Background(), config.ModelConfig{
		ModelName: modelName, ApiType: "openai", ApiURL: f.srv.URL + "/v1/chat/completions", ApiKey: apiKey,
	})
	require.NotNil(t, api)
	require.Equal(t, "ollama", api.Stack)
	return api, trace
}

func (f *ollamaFixture) authSeen(path string) []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.auth[path]
}

func TestProbeOllamaShowDocsSample(t *testing.T) {
	f := newOllamaFixture(t, ollamaShowLlama8B, map[string]any{"models": []any{}})
	api, trace := f.detect(t, "llama3:8b", "secret")

	require.Equal(t, "llama", api.ModelFamily)
	require.Nil(t, api.Thinking)
	caps := api.Capabilities
	require.NotNil(t, caps)
	require.Equal(t, int64(8192), *caps.Context, "a trained window alone stands in for the served one")
	require.Nil(t, caps.ContextTrained)
	require.Equal(t, "ollama:/api/show.model_info.llama.context_length", api.Evidence["capabilities.context"])
	require.NotNil(t, caps.Modalities)
	require.Equal(t, []string{"image"}, caps.Modalities.Input)
	require.Equal(t, "ollama:/api/show.capabilities", api.Evidence["capabilities.modalities.input"])
	require.Equal(t, "Q4_0", caps.Quantization)
	require.Equal(t, "ollama:/api/show.details.quantization_level", api.Evidence["capabilities.quantization"])
	require.Nil(t, caps.Tools, "completion alone says nothing")
	require.Nil(t, caps.Reasoning)
	require.Nil(t, caps.Embeddings)
	require.NotContains(t, api.Evidence, "thinking.default")

	require.Contains(t, trace, "ollama /api/show capabilities lists vision -> modalities.input image")
	require.Contains(t, trace, "ollama /api/show model_info.llama.context_length = 8192 -> contextTrained")
	require.Contains(t, trace, "ollama /api/show details.quantization_level = Q4_0 -> quantization")
	require.Contains(t, trace, "ollama /api/ps does not list the configured model as loaded; context stays as configured")

	for _, path := range []string{"/api/tags", "/api/show", "/api/ps"} {
		require.Equal(t, []string{""}, f.authSeen(path), "%s is a local API: no key unless it asks", path)
	}
}

func TestProbeOllamaThinkingModelLoaded(t *testing.T) {
	f := newOllamaFixture(t, ollamaShowQwen3Thinking, ollamaPSLoaded("qwen3:32b", 32768))
	api, trace := f.detect(t, "qwen3:32b", "")

	caps := api.Capabilities
	require.NotNil(t, caps)
	require.Equal(t, int64(32768), *caps.Context)
	require.Equal(t, "ollama:/api/ps.models.context_length", api.Evidence["capabilities.context"])
	require.Equal(t, int64(40960), *caps.ContextTrained)
	require.Equal(t, "ollama:/api/show.model_info.qwen3.context_length", api.Evidence["capabilities.contextTrained"])
	require.Equal(t, true, *caps.Tools)
	require.Equal(t, "ollama:/api/show.capabilities", api.Evidence["capabilities.tools"])
	require.Equal(t, true, *caps.Reasoning)
	require.Equal(t, "ollama:/api/show.thinking.values", api.Evidence["capabilities.reasoning"])
	require.Equal(t, "Q4_K_M", caps.Quantization)

	require.NotNil(t, api.Thinking)
	require.Equal(t, system.ThinkingModeControllable, api.Thinking.Mode)
	require.Equal(t, "off", api.Thinking.Default)
	require.Equal(t, "ollama:/api/show.thinking.default", api.Evidence["thinking.default"])

	effort := api.Bindings[system.IntentReasoningEffort]
	require.NotNil(t, effort)
	require.Equal(t, "reasoning_effort", effort.Param)
	require.Equal(t, []string{"none", "low", "high"}, effort.EnumValues)
	require.Equal(t, "ollama:/api/show.thinking.values", api.Evidence["bindings."+system.IntentReasoningEffort])
	require.Equal(t, "none", api.Bindings[system.IntentReasoningDisable].Value)
	require.Equal(t, "low", api.Bindings[system.IntentReasoningEnable].Value)

	require.Contains(t, trace, "ollama /api/show parameters num_ctx = 16384 -> context (configured beats details.context_length)")
	require.Contains(t, trace, "ollama /api/ps models.context_length = 32768 -> context (loaded beats ollama:/api/show.parameters.num_ctx)")
	require.Contains(t, trace, "ollama /api/show thinking.values levels -> reasoning efforts none|low|high")
	require.Contains(t, trace, "ollama /api/show thinking.default -> thinking.default off")
}

func TestProbeOllamaThinkingValues(t *testing.T) {
	show := func(arch string, capabilities []string, thinking map[string]any) map[string]any {
		return map[string]any{
			"template":     "{{ .Prompt }}",
			"capabilities": capabilities,
			"thinking":     thinking,
			"model_info":   map[string]any{"general.architecture": arch},
		}
	}
	cases := []struct {
		name  string
		model string
		show  map[string]any
		check func(t *testing.T, api *system.ModelApiSpec, trace []string)
	}{
		{
			name:  "only false reports no reasoning even when the capability list says thinking",
			model: "llama3:8b",
			show:  show("llama", []string{"completion", "thinking"}, map[string]any{"values": []any{false}, "default": false}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.NotNil(t, api.Capabilities)
				require.Equal(t, false, *api.Capabilities.Reasoning)
				require.Equal(t, "ollama:/api/show.thinking.values", api.Evidence["capabilities.reasoning"])
				require.Nil(t, api.Thinking)
				require.Nil(t, api.Bindings[system.IntentReasoningDisable])
				require.Nil(t, api.Bindings[system.IntentReasoningEnable])
				require.Nil(t, api.Bindings[system.IntentReasoningEffort])
				require.NotContains(t, api.Evidence, "thinking.default")
				require.Contains(t, trace, "ollama /api/show thinking.values lists only false -> reasoning false")
			},
		},
		{
			name:  "booleans only are a toggle with the stack's level list",
			model: "qwen3:8b",
			show:  show("qwen3", []string{"completion", "thinking"}, map[string]any{"values": []any{true, false}, "default": true}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Equal(t, true, *api.Capabilities.Reasoning)
				require.Equal(t, system.ThinkingModeControllable, api.Thinking.Mode)
				require.Equal(t, "on", api.Thinking.Default)
				require.Equal(t, "none", api.Bindings[system.IntentReasoningDisable].Value)
				require.Equal(t, "medium", api.Bindings[system.IntentReasoningEnable].Value)
				require.Equal(t, []string{"low", "medium", "high", "max", "none"}, api.Bindings[system.IntentReasoningEffort].EnumValues)
				require.NotContains(t, api.Evidence, "bindings."+system.IntentReasoningEffort)
			},
		},
		{
			name:  "levels only tune the effort and keep the reported default level",
			model: "gpt-oss:20b",
			show:  show("gptoss", []string{"completion", "thinking"}, map[string]any{"values": []any{"low", "medium", "high"}, "default": "medium"}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Equal(t, "gpt-oss", api.ModelFamily)
				require.Equal(t, system.ThinkingModeTunable, api.Thinking.Mode)
				require.Equal(t, "medium", api.Thinking.Default)
				require.Equal(t, "ollama:/api/show.thinking.default", api.Evidence["thinking.default"])
				require.Nil(t, api.Bindings[system.IntentReasoningDisable])
				require.Equal(t, []string{"low", "medium", "high"}, api.Bindings[system.IntentReasoningEffort].EnumValues)
			},
		},
		{
			name:  "levels without false drop the none switch",
			model: "qwen3:8b",
			show:  show("qwen3", []string{"completion", "thinking"}, map[string]any{"values": []any{true, "low", "high"}}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Equal(t, system.ThinkingModeControllable, api.Thinking.Mode)
				require.Empty(t, api.Thinking.Default)
				require.Nil(t, api.Bindings[system.IntentReasoningDisable])
				require.Equal(t, "low", api.Bindings[system.IntentReasoningEnable].Value)
				require.Equal(t, []string{"low", "high"}, api.Bindings[system.IntentReasoningEffort].EnumValues)
			},
		},
		{
			name:  "only true accepts no off switch: reasoning is mandatory",
			model: "qwen3:8b",
			show:  show("qwen3", []string{"completion", "thinking"}, map[string]any{"values": []any{true}, "default": true}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Equal(t, true, *api.Capabilities.Reasoning)
				require.Equal(t, "ollama:/api/show.thinking.values", api.Evidence["capabilities.reasoning"])
				require.Equal(t, system.ThinkingModeAlwaysOn, api.Thinking.Mode)
				require.Nil(t, api.Bindings[system.IntentReasoningDisable])
				require.Nil(t, api.Bindings[system.IntentReasoningEnable])
				require.Nil(t, api.Bindings[system.IntentReasoningEffort], "no level was listed")
				require.Contains(t, trace, "ollama /api/show thinking.values lists only true -> reasoning mandatory")
			},
		},
		{
			name:  "a values string is not a list: the capability list decides",
			model: "qwen3:8b",
			show:  show("qwen3", []string{"completion", "thinking"}, map[string]any{"values": "low", "default": "low"}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Nil(t, api.Capabilities)
				require.Equal(t, system.ThinkingModeControllable, api.Thinking.Mode)
				require.Equal(t, "none", api.Bindings[system.IntentReasoningDisable].Value)
				require.Equal(t, []string{"low", "medium", "high", "max", "none"}, api.Bindings[system.IntentReasoningEffort].EnumValues, "the stack's list, not a report")
				require.NotContains(t, api.Evidence, "bindings."+system.IntentReasoningEffort)
				require.NotContains(t, api.Evidence, "thinking.default")
			},
		},
		{
			name:  "a numeric entry among booleans is skipped: toggle only, no efforts",
			model: "qwen3:8b",
			show:  show("qwen3", []string{"completion", "thinking"}, map[string]any{"values": []any{true, false, 3}, "default": 1}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Equal(t, true, *api.Capabilities.Reasoning)
				require.Equal(t, system.ThinkingModeControllable, api.Thinking.Mode)
				require.Equal(t, "none", api.Bindings[system.IntentReasoningDisable].Value)
				require.Equal(t, []string{"low", "medium", "high", "max", "none"}, api.Bindings[system.IntentReasoningEffort].EnumValues)
				require.NotContains(t, api.Evidence, "bindings."+system.IntentReasoningEffort)
				require.Empty(t, api.Thinking.Default, "a numeric default is not on/off nor a level")
				require.NotContains(t, api.Evidence, "thinking.default")
			},
		},
		{
			name:  "no thinking object falls back to the capability list",
			model: "qwen3:8b",
			show:  show("qwen3", []string{"completion", "thinking"}, nil),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Equal(t, system.ThinkingModeControllable, api.Thinking.Mode)
				require.Equal(t, "none", api.Bindings[system.IntentReasoningDisable].Value)
				require.Nil(t, api.Capabilities, "the capability list is not a thinking.values report")
				require.NotContains(t, api.Evidence, "thinking.default")
			},
		},
		{
			name:  "an empty values list is no report",
			model: "llama3:8b",
			show:  show("llama", []string{"completion"}, map[string]any{"values": []any{}}),
			check: func(t *testing.T, api *system.ModelApiSpec, trace []string) {
				require.Nil(t, api.Thinking)
				require.Nil(t, api.Capabilities)
			},
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f := newOllamaFixture(t, c.show, nil)
			api, trace := f.detect(t, c.model, "")
			c.check(t, api, trace)
		})
	}
}

func TestProbeOllamaContextPrecedence(t *testing.T) {
	show := func(details map[string]any, parameters string) map[string]any {
		return map[string]any{
			"template":   "{{ .Prompt }}",
			"details":    details,
			"parameters": parameters,
			"model_info": map[string]any{"general.architecture": "llama", "llama.context_length": 131072},
		}
	}
	cases := []struct {
		name        string
		model       string
		show        map[string]any
		ps          any
		wantContext int64
		wantSource  string
		wantTrace   string
	}{
		{
			name: "trained alone", model: "llama3:8b",
			show: show(nil, ""), wantContext: 131072, wantSource: "ollama:/api/show.model_info.llama.context_length",
		},
		{
			name: "details.context_length is served", model: "llama3:8b",
			show: show(map[string]any{"context_length": 4096}, ""), wantContext: 4096, wantSource: "ollama:/api/show.details.context_length",
			wantTrace: "ollama /api/show details.context_length = 4096 -> context",
		},
		{
			name: "num_ctx beats details", model: "llama3:8b",
			show: show(map[string]any{"context_length": 4096}, "num_ctx                        8192\nstop \"x\""), wantContext: 8192, wantSource: "ollama:/api/show.parameters.num_ctx",
		},
		{
			name: "loaded beats num_ctx", model: "llama3:8b",
			show: show(nil, "num_ctx 8192"), ps: ollamaPSLoaded("llama3:8b", 32768), wantContext: 32768, wantSource: "ollama:/api/ps.models.context_length",
			wantTrace: "ollama /api/ps models.context_length = 32768 -> context (loaded beats ollama:/api/show.parameters.num_ctx)",
		},
		{
			name: "loaded model matched by the bare id", model: "llama3:8b:tee=1",
			show: show(nil, ""), ps: ollamaPSLoaded("llama3:8b", 32768), wantContext: 32768, wantSource: "ollama:/api/ps.models.context_length",
			wantTrace: "ollama /api/ps models.context_length = 32768 -> context (loaded)",
		},
		{
			name: "an untagged name is the latest tag", model: "llama3",
			show: show(nil, ""), ps: ollamaPSLoaded("llama3:latest", 32768), wantContext: 32768, wantSource: "ollama:/api/ps.models.context_length",
		},
		{
			name: "another loaded model does not count", model: "llama3:8b",
			show: show(nil, "num_ctx 8192"), ps: ollamaPSLoaded("mistral:latest", 32768), wantContext: 8192, wantSource: "ollama:/api/show.parameters.num_ctx",
			wantTrace: "ollama /api/ps does not list the configured model as loaded; context stays as configured",
		},
		{
			name: "a loaded context that is not a JSON number is ignored", model: "llama3:8b",
			show: show(nil, "num_ctx 8192"), ps: ollamaPSLoaded("llama3:8b", "32768"), wantContext: 8192, wantSource: "ollama:/api/show.parameters.num_ctx",
			wantTrace: "ollama /api/ps lists the model but context_length is not a positive JSON number; context stays as configured",
		},
		{
			name: "non-positive values are rejected", model: "llama3:8b",
			show: show(map[string]any{"context_length": 0}, "num_ctx -1"), ps: ollamaPSLoaded("llama3:8b", 0), wantContext: 131072, wantSource: "ollama:/api/show.model_info.llama.context_length",
			wantTrace: "ollama /api/ps lists the model but context_length is not a positive JSON number; context stays as configured",
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f := newOllamaFixture(t, c.show, c.ps)
			api, trace := f.detect(t, c.model, "")
			require.NotNil(t, api.Capabilities)
			require.NotNil(t, api.Capabilities.Context)
			require.Equal(t, c.wantContext, *api.Capabilities.Context)
			require.Equal(t, c.wantSource, api.Evidence["capabilities.context"])
			if c.wantTrace != "" {
				require.Contains(t, trace, c.wantTrace)
			}
		})
	}
}

func TestProbeOllamaRejectsOddTrainedContext(t *testing.T) {
	for name, value := range map[string]any{"string": "8192", "fraction": 8192.5, "beyond 1<<31": 4294967296} {
		t.Run(name, func(t *testing.T) {
			f := newOllamaFixture(t, map[string]any{
				"template":   "{{ .Prompt }}",
				"model_info": map[string]any{"general.architecture": "llama", "llama.context_length": value},
			}, nil)
			api, trace := f.detect(t, "llama3:8b", "")
			if api.Capabilities != nil {
				require.Nil(t, api.Capabilities.Context)
				require.Nil(t, api.Capabilities.ContextTrained)
			}
			require.NotContains(t, api.Evidence, "capabilities.contextTrained")
			require.NotContains(t, api.Evidence, "capabilities.context")
			for _, line := range trace {
				require.NotContains(t, line, "-> contextTrained")
			}
		})
	}
}

func TestProbeOllamaCapabilityList(t *testing.T) {
	cases := []struct {
		name         string
		capabilities []string
		check        func(t *testing.T, caps *system.ModelCapabilities)
	}{
		{
			name: "embedding", capabilities: []string{"embedding"},
			check: func(t *testing.T, caps *system.ModelCapabilities) {
				require.Equal(t, true, *caps.Embeddings)
				require.Nil(t, caps.Modalities)
			},
		},
		{
			name: "vision and audio", capabilities: []string{"completion", "vision", "audio", "vision"},
			check: func(t *testing.T, caps *system.ModelCapabilities) {
				require.Equal(t, []string{"image", "audio"}, caps.Modalities.Input)
				require.Nil(t, caps.Tools)
			},
		},
		{
			name: "tools", capabilities: []string{"completion", "tools", "insert"},
			check: func(t *testing.T, caps *system.ModelCapabilities) {
				require.Equal(t, true, *caps.Tools)
				require.Nil(t, caps.Modalities)
				require.Nil(t, caps.Embeddings)
				require.Empty(t, caps.Quantization, "a numeric quantization_level is not a label")
			},
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f := newOllamaFixture(t, map[string]any{
				"template": "{{ .Prompt }}", "capabilities": c.capabilities,
				"details": map[string]any{"quantization_level": 4},
			}, nil)
			api, _ := f.detect(t, "m:latest", "")
			require.NotNil(t, api.Capabilities)
			c.check(t, api.Capabilities)
			for key, source := range api.Evidence {
				if len(key) > len("capabilities.") && key[:len("capabilities.")] == "capabilities." && key != "capabilities.reasoning" {
					require.Equal(t, "ollama:/api/show.capabilities", source, key)
				}
			}
		})
	}
}

func TestProbeOllamaRejectsOddArchitectureKey(t *testing.T) {
	f := newOllamaFixture(t, map[string]any{
		"template":   "{{ .Prompt }}",
		"model_info": map[string]any{"general.architecture": "http://evil.example", "http://evil.example.context_length": 8192},
	}, nil)
	api, _ := f.detect(t, "m:latest", "")
	require.Nil(t, api.Capabilities)
	for _, source := range api.Evidence {
		require.NotContains(t, source, "evil")
	}
}

// A proxy in front of Ollama that guards every path: each request is
// repeated with the key exactly once.
func TestProbeOllamaRetriesWithKeyOnUnauthorized(t *testing.T) {
	calls := map[string][]string{}
	var mu sync.Mutex
	guarded := func(status int, body any) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			mu.Lock()
			calls[r.URL.Path] = append(calls[r.URL.Path], r.Header.Get("Authorization"))
			mu.Unlock()
			if r.Header.Get("Authorization") != "Bearer secret" {
				w.WriteHeader(status)
				return
			}
			jsonHandler(body)(w, r)
		}
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/api/tags", guarded(http.StatusUnauthorized, map[string]any{"models": []map[string]any{{"name": "x"}}}))
	mux.HandleFunc("/api/show", guarded(http.StatusForbidden, map[string]any{"template": "{{ .Prompt }}", "capabilities": []string{"completion", "tools"}}))
	mux.HandleFunc("/api/ps", guarded(http.StatusUnauthorized, ollamaPSLoaded("m:latest", 32768)))
	srv := httptest.NewServer(mux)
	defer srv.Close()

	api := newTestDetector().Detect(context.Background(), config.ModelConfig{
		ModelName: "m:latest", ApiType: "openai", ApiURL: srv.URL + "/v1/chat/completions", ApiKey: "secret",
	})
	require.NotNil(t, api)
	require.Equal(t, "ollama", api.Stack)
	mu.Lock()
	defer mu.Unlock()
	for _, path := range []string{"/api/tags", "/api/show", "/api/ps"} {
		require.Equal(t, []string{"", "Bearer secret"}, calls[path], path)
	}
	require.Equal(t, true, *api.Capabilities.Tools)
	require.Equal(t, int64(32768), *api.Capabilities.Context)
}

// Without a configured key a 401 is final: nothing to retry with.
func TestProbeOllamaNoKeyNoRetry(t *testing.T) {
	var calls []string
	var mu sync.Mutex
	mux := http.NewServeMux()
	mux.HandleFunc("/api/tags", jsonHandler(map[string]any{"models": []map[string]any{{"name": "x"}}}))
	mux.HandleFunc("/api/show", func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		calls = append(calls, r.Header.Get("Authorization"))
		mu.Unlock()
		w.WriteHeader(http.StatusUnauthorized)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	api := newTestDetector().Detect(context.Background(), config.ModelConfig{
		ModelName: "m:latest", ApiType: "openai", ApiURL: srv.URL + "/v1/chat/completions",
	})
	require.NotNil(t, api)
	require.Equal(t, "ollama", api.Stack)
	require.Equal(t, []string{""}, calls)
	require.Nil(t, api.Capabilities)
}
